		<div class="pdf24_ pdf24_02">
			<div class="pdf24_03">
				<img src="data:image/png;base64," alt="" class="pdf24_04" />
			</div>
			<div class="pdf24_view">
				<div class="pdf24_05 pdf24_06">
					<div class="pdf24_01" style="left:19.9351em;top:2.88em;"><span class="pdf24_07 pdf24_08 pdf24_09" style="word-spacing:0em;">Request for Taxpayer &nbsp;</span></div>
					<div class="pdf24_01" style="left:15.3384em;top:4.1295em;"><span class="pdf24_07 pdf24_08 pdf24_09" style="word-spacing:0em;">Identification Number and Certification &nbsp;</span></div>
					<div class="pdf24_01" style="left:14.3338em;top:5.7567em;"><span class="pdf24_10 pdf24_11 pdf24_09" style="word-spacing:0em;">Go to </span><a href="http://www.irs.gov/FormW9" target="_blank"><span class="pdf24_12 pdf24_11 pdf24_09" style="word-spacing:0em;">www.irs.gov/FormW9 </span></a><span class="pdf24_10 pdf24_11 pdf24_09" style="word-spacing:0em;">for instructions and the latest information. &nbsp;</span></div>
					<div class="pdf24_01" style="left:41.3833em;top:3.5383em;"><span class="pdf24_13 pdf24_11 pdf24_09" style="word-spacing:0em;">Give form to the &nbsp;</span></div>
					<div class="pdf24_01" style="left:41.3833em;top:4.4383em;"><span class="pdf24_13 pdf24_11 pdf24_09" style="word-spacing:0em;">requester. Do not &nbsp;</span></div>
					<div class="pdf24_01" style="left:41.3833em;top:5.3382em;"><span class="pdf24_13 pdf24_11 pdf24_09" style="word-spacing:0em;">send to the IRS. &nbsp;</span></div>
					<div class="pdf24_01" style="left:3em;top:3.792em;"><span class="pdf24_14 pdf24_15 pdf24_09">Form &nbsp;</span></div>
					<div class="pdf24_01" style="left:3em;top:4.5773em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">(Rev. March 2024) &nbsp;</span></div>
					<div class="pdf24_01" style="left:4.6858em;top:2.4033em;"><span class="pdf24_16 pdf24_17 pdf24_09">W-9 &nbsp;</span></div>
					<div class="pdf24_01 pdf24_18" style="left:3em;top:5.4138em;"><span class="pdf24_19 pdf24_15 pdf24_09" style="word-spacing:0em;">Department of the Treasury &nbsp;</span></div>
					<div class="pdf24_01 pdf24_18" style="left:3em;top:6.1138em;"><span class="pdf24_19 pdf24_15 pdf24_09" style="word-spacing:0em;">Internal Revenue Service &nbsp;</span></div>
					<div class="pdf24_01" style="left:3em;top:6.9952em;"><span class="pdf24_10 pdf24_11 pdf24_09" style="word-spacing:0em;">Before you begin. </span><span class="pdf24_20 pdf24_15 pdf24_09" style="word-spacing:0em;">For guidance related to the purpose of Form W-9, see </span><span class="pdf24_21 pdf24_22 pdf24_09" style="word-spacing:0em;">Purpose of Form</span><span class="pdf24_20 pdf24_15 pdf24_09" style="word-spacing:0em;">, below. &nbsp;</span></div>
					<div class="pdf24_01" style="left:5.1333em;top:8.0172em;"><span class="pdf24_23 pdf24_11 pdf24_09">1</span></div>
					<div class="pdf24_01" style="left:6.1063em;top:8.0306em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Name of entity/individual. An entry is required. (For a sole proprietor or disregarded entity, enter the owner’s name on line 1, and enter the business/disregarded &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1332em;top:8.7306em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">entity’s name on line 2.) &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1417em;top:9.7081em;"><span class="pdf24_24 pdf24_25 pdf24_26" style="word-spacing:0.0003em;">{{ $w9->vendor_company_name ?? '' }} &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1063em;top:11.0306em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Business name/disregarded entity name, if different from above. &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1417em;top:11.7156em;"><span class="pdf24_24 pdf24_25 pdf24_26">{{ $decrypted['business_name'] }} &nbsp;</span></div>
					<div class="pdf24_01" style="left:5.1333em;top:11.0172em;"><span class="pdf24_23 pdf24_11 pdf24_09">2</span></div>
					<div class="pdf24_01" style="left:5.1333em;top:13.0168em;"><span class="pdf24_23 pdf24_11 pdf24_09" style="word-spacing:0.278em;">3a </span><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Check the appropriate box for federal tax classification of the entity/individual whose name is entered on line 1. Check &nbsp;</span></div>
					<div class="pdf24_01" style="left:38.1333em;top:13.1003em;"><span class="pdf24_23 pdf24_11 pdf24_09" style="word-spacing:0.278em;">4 </span><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Exemptions (codes apply only to &nbsp;</span></div>
					<div class="pdf24_01" style="left:38.8001em;top:13.8138em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">certain entities, not individuals; &nbsp;</span></div>
					<div class="pdf24_01" style="left:38.8001em;top:14.5138em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">see instructions on page 3): &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1332em;top:13.7168em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">only </span><span class="pdf24_23 pdf24_11 pdf24_09" style="word-spacing:0em;">one </span><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">of the following seven boxes. &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1417em;top:14.5506em;"><span class="pdf24_24 pdf24_25 pdf24_09">x</span></div>
					<div class="pdf24_01" style="left:7.2167em;top:14.9471em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Individual/sole proprietor &nbsp;</span></div>
					<div class="pdf24_01" style="left:16.1333em;top:14.9471em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">C corporation &nbsp;</span></div>
					<div class="pdf24_01" style="left:22.1333em;top:14.9471em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">S corporation &nbsp;</span></div>
					<div class="pdf24_01" style="left:28.1332em;top:14.9471em;"><span class="pdf24_14 pdf24_15 pdf24_09">Partnership &nbsp;</span></div>
					<div class="pdf24_01" style="left:33.5334em;top:14.9471em;"><span class="pdf24_14 pdf24_15 pdf24_09">Trust/estate &nbsp;</span></div>
					<div class="pdf24_01" style="left:33.9995em;top:16.072em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:45.8267em;top:15.6131em;"><span class="pdf24_24 pdf24_25 pdf24_09">1</span></div>
					<div class="pdf24_01 pdf24_18" style="left:38.1333em;top:15.9887em;"><span class="pdf24_19 pdf24_15 pdf24_09" style="word-spacing:0em;">Exempt payee code (if any) &nbsp;</span></div>
					<div class="pdf24_01" style="left:7.2em;top:16.072em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">LLC. Enter the tax classification (C = C corporation, S = S corporation, P = Partnership) &nbsp;</span></div>
					<div class="pdf24_01" style="left:31em;top:16.072em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:31.9998em;top:16.072em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:32.9997em;top:16.072em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01 pdf24_27" style="left:7.2em;top:16.8817em;"><span class="pdf24_28 pdf24_11 pdf24_09" style="word-spacing:0em;">Note: </span><span class="pdf24_29 pdf24_15 pdf24_09" style="word-spacing:0em;">Check the “LLC” box above and, in the entry space, enter the appropriate code (C, S, or P) for the tax &nbsp;</span></div>
					<div class="pdf24_01 pdf24_27" style="left:7.2em;top:17.5408em;"><span class="pdf24_29 pdf24_15 pdf24_09" style="word-spacing:0em;">classification of the LLC, unless it is a disregarded entity. A disregarded entity should instead check the appropriate &nbsp;</span></div>
					<div class="pdf24_01 pdf24_27" style="left:7.2em;top:18.1866em;"><span class="pdf24_29 pdf24_15 pdf24_09" style="word-spacing:0em;">box for the tax classification of its owner. &nbsp;</span></div>
					<div class="pdf24_01" style="left:38.1333em;top:17.4973em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Exemption from Foreign Account Tax &nbsp;</span></div>
					<div class="pdf24_01" style="left:38.1333em;top:18.1973em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Compliance Act (FATCA) reporting &nbsp;</span></div>
					<div class="pdf24_01" style="left:38.1705em;top:18.947em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">code (if any) &nbsp;</span></div>
					<div class="pdf24_01" style="left:7.2em;top:19.1137em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Other (see instructions) &nbsp;</span></div>
					<div class="pdf24_01" style="left:43.2283em;top:18.9206em;"><span class="pdf24_24 pdf24_25 pdf24_09">A</span></div>
					<div class="pdf24_01" style="left:5.1333em;top:20.4503em;"><span class="pdf24_23 pdf24_11 pdf24_09" style="word-spacing:0.1394em;">3b </span><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">If on line 3a you checked “Partnership” or “Trust/estate,” or checked “LLC” and entered “P” as its tax classification, &nbsp;</span></div>
					<div class="pdf24_01" style="left:38.74em;top:20.8277em;"><span class="pdf24_30 pdf24_22 pdf24_09" style="word-spacing:0em;">(Applies to accounts maintained &nbsp;</span></div>
					<div class="pdf24_01" style="left:39.4534em;top:21.5277em;"><span class="pdf24_30 pdf24_22 pdf24_09" style="word-spacing:0em;">outside the United States.) &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1334em;top:21.1637em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0.095em;">and you are providing this form to a partnership, trust, or estate in which you have an ownership interest, check &nbsp;</span></div>
					<div class="pdf24_01" style="left:6.1358em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">this box if you have any foreign partners, owners, or beneficiaries. See instructions</span><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0.391em;">&nbsp;</span><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">. &nbsp;</span></div>
					<div class="pdf24_01" style="left:29.0024em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:30.0023em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:31.0021em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:32.0019em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:33.0017em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:34.0016em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:35.0014em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:36.0012em;top:21.8637em;"><span class="pdf24_14 pdf24_15 pdf24_09">.</span></div>
					<div class="pdf24_01" style="left:5.1333em;top:23.0172em;"><span class="pdf24_23 pdf24_11 pdf24_09">5</span></div>
					<div class="pdf24_01" style="left:5.1333em;top:25.017em;"><span class="pdf24_23 pdf24_11 pdf24_09">6</span></div>
					<div class="pdf24_01" style="left:5.1333em;top:27.0171em;"><span class="pdf24_23 pdf24_11 pdf24_09">7</span></div>
					<div class="pdf24_01" style="left:6.1063em;top:23.0306em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Address (number, street, and apt. or suite no.). See instructions. &nbsp;</span></div>
					<div class="pdf24_01" style="left:5.6692em;top:23.6447em;"><span class="pdf24_24 pdf24_25 pdf24_26" style="word-spacing:0.0002em;">{{ $decrypted['address']  }} &nbsp;</span></div>
					<div class="pdf24_01" style="left:32.7333em;top:23.0306em;"><span class="pdf24_14 pdf24_15 pdf24_09" style="word-spacing:0em;">Requester’s name and address (optional) &nbsp;</span></div>
